mutations.before:
// The brief's template (D120/D123, C3) rides the frame exactly as it
// rides the run: the preview draws the brief's order, not the
// canonical fallback.
template: brief.template,

function drawHtml(c: LayerDrawContext): void {
  const { ctx, prepared, layer } = c;
  if (layer.elements === undefined || layer.elements.length === 0) {
    return;
  }

mutations.after:
function drawHtml(c: LayerDrawContext): void {
  const { ctx, prepared, layer } = c;
  if (layer.elements !== undefined) {
    return;
  }
  if (layer.elements === undefined || layer.elements.length === 0) {
    return;
  }
